-- ============================================================
--  Тема «Умовні речення, Wishes, Unreal Past (Conditionals)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/conditionals.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
-- тип вправи «translate» (переклад і письмо) дозволено в exercises.type
alter table public.exercises drop constraint if exists exercises_type_check;
alter table public.exercises add constraint exercises_type_check
  check (type in ('order', 'choice', 'gap', 'cross', 'abcd', 'translate'));
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$conditionals$g0$, $g1$Умовні речення, Wishes, Unreal Past (Conditionals)$g1$, $g2$Умовні речення 1, 2 і 3 типу, wish та if only, Unreal Past (suppose, as if, it's time, I'd rather sb), had better і would rather, prefer.$g2$, 11, $g3$[{"slug":"cond_first","title":"Перший тип: реальна умова","description":"If, when, until, unless, as soon as: Present Simple замість will після сполучника, а також Present Continuous і Perfect у підрядній частині."},{"slug":"cond_second","title":"Другий тип: нереальне зараз і порада If I were you","description":"If + Past Simple → would + V для нереальної умови в теперішньому, і формула поради «на вашому місці»."},{"slug":"cond_third","title":"Третій тип: нереальне минуле","description":"If + Past Perfect → would have + V3: жаль і критика через те, що сталося, а змінити вже не можна."},{"slug":"cond_unreal","title":"Нереальні умови: якби…","description":"Умовні речення 2 і 3 типу, а також unless, provided, only if та інверсія Had I known / Were I you."},{"slug":"cond_wish","title":"Wish і if only: жаль і побажання","description":"Жаль про теперішнє й минуле, неможливе бажання змін, wish + would для роздратування."},{"slug":"cond_unrealpast","title":"Уявна ситуація: suppose, as if, it's time","description":"Past Simple для уявного теперішнього й Past Perfect для уявного минулого після suppose, as if, it's time, I'd rather sb."},{"slug":"cond_rather","title":"Порада й вибір: had better, would rather, prefer","description":"Коли краще зробити щось зараз, коли краще було б зробити інакше, і як висловити перевагу."},{"slug":"cond_mix","title":"Змішана практика: умови й побажання","description":"Тексти й перефразування, де змішано умовні речення, wish та Unreal Past. Окремої теорії тут немає.","mix":true}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$ct_1$g4$, $g5$Перший тип: реальна умова$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Перший тип","kicker":"Реальна умова","lead":"Умовні речення першого типу (First Conditional) говорять про <b>реальну або цілком можливу</b> ситуацію в майбутньому: якщо виконається умова, буде й наслідок.","tiles":[{"role":"умова","label":"If + Present Simple","tone":"colour"},{"role":"наслідок","label":"will / can / may / should + V","tone":"noun"}],"legend":[{"tone":"colour","label":"Після if майбутній час не вживаємо: <i>If you buy</i>, а не <s>If you will buy</s>"},{"tone":"noun","label":"У головній частині: will + дієслово без to, а також can, may, should"}],"examples":[{"text":"He <b>will paint</b> the fence <b>if</b> you <b>buy</b> some paint.","plain":"He will paint the fence if you buy some paint.","note":"умова й наслідок"},{"text":"She <b>can give</b> you the dictionary <b>if</b> she <b>doesn't need</b> it.","plain":"She can give you the dictionary if she doesn't need it.","note":"модальне дієслово в головній частині"},{"text":"<b>If</b> we <b>help</b> her, she <b>will finish</b> the work soon.","plain":"If we help her, she will finish the work soon.","note":"if-частина першою: ставимо кому"},{"text":"She <b>will finish</b> the work soon <b>if</b> we <b>help</b> her.","plain":"She will finish the work soon if we help her.","note":"if-частина другою: коми немає"}],"note":"Головна й підрядна частини можуть мінятися місцями. Якщо речення починається з if-частини, її відокремлюємо комою."}$g8$::jsonb, null, 0, $g9$cond_first$g9$
from public.topics where slug = $g10$conditionals$g10$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$ct_2$g11$, $g12$If, when, until, unless, as soon as$g12$, $g13$elementary$g13$, $g14$cases$g14$, $g15${"kicker":"Сполучники умови","lead":"Усі ці слова вимагають після себе <b>теперішнього часу</b>, хоча мова про майбутнє. Відрізняються вони змістом.","cards":[{"icon":"if","title":"If: умова, яка може й не виконатися","text":"Ми висловлюємо припущення: чи буде вільний час, ми ще не знаємо.","example":"She will go shopping <b>if</b> she has time.","examplePlain":"She will go shopping if she has time."},{"icon":"when","title":"When: дія, яка обов'язково відбудеться","text":"Ми впевнені, що це станеться. Питання лише коли.","example":"She will go shopping <b>when</b> she has time.","examplePlain":"She will go shopping when she has time."},{"icon":"until","title":"Until / till: «поки не»","text":"Дія триває до моменту, коли відбудеться інша. Після until теперішній час.","example":"The doctor won't prescribe any medicine <b>until</b> he examines the patient.","examplePlain":"The doctor won't prescribe any medicine until he examines the patient."},{"icon":"unless","title":"Unless = if … not","text":"Після unless дієслово стоїть у ствердній формі, not не додаємо. У питаннях unless не вживаємо: лише if … not.","example":"We won't have a break <b>unless</b> we finish our project. (= if we don't finish)","examplePlain":"We won't have a break unless we finish our project. (= if we don't finish)"},{"icon":"as soon as","title":"As soon as: «щойно»","text":"Одна дія йде одразу за іншою.","example":"We will see him <b>as soon as</b> the bus arrives.","examplePlain":"We will see him as soon as the bus arrives."},{"icon":"0","title":"Нульовий тип: if = when","text":"Коли мова про загальну істину чи звичку, if і when означають одне й те саме, а в обох частинах стоїть Present Simple.","example":"<b>If</b> (<b>when</b>) I have a good mood, I always listen to music.","examplePlain":"If (when) I have a good mood, I always listen to music."}]}$g15$::jsonb, null, 1, $g16$cond_first$g16$
from public.topics where slug = $g17$conditionals$g17$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$ct_3$g18$, $g19$Інші теперішні часи після if$g19$, $g20$intermediate$g20$, $g21$cases$g21$, $g22${"kicker":"Не лише Present Simple","lead":"У підрядній частині можуть стояти й інші теперішні часи, якщо цього вимагає зміст. Правила їхнього вживання лишаються незмінними.","cards":[{"icon":"~","title":"Present Continuous: дія триває зараз","text":"Ми говоримо про те, що відбувається в цей момент.","example":"If you <b>are still doing</b> your homework, we won't go to the cinema.","examplePlain":"If you are still doing your homework, we won't go to the cinema."},{"icon":"✓","title":"Present Perfect: дія вже завершена","text":"Результат до цього моменту: уже зроблено або ще не зроблено (yet, already).","example":"If you <b>have done</b> your homework, we'll go to the cinema.","examplePlain":"If you have done your homework, we'll go to the cinema."},{"icon":"⌛","title":"Present Perfect Continuous: тривалість до цього моменту","text":"Дія триває вже певний час (for, since).","example":"If she <b>has been cleaning</b> the flat for two hours already, we should help her.","examplePlain":"If she has been cleaning the flat for two hours already, we should help her."}]}$g22$::jsonb, null, 2, $g23$cond_first$g23$
from public.topics where slug = $g24$conditionals$g24$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$ct_4$g25$, $g26$Стоп-калька: will після if, when, until$g26$, $g27$intermediate$g27$, $g28$traps$g28$, $g29${"kicker":"Захист від рідної мови","lead":"В українській «якщо ти <i>будеш</i> вільний» стоїть у майбутньому. В англійській умова після сполучника має теперішній час.","items":[{"title":"«Якщо ти будеш вільний, я зателефоную»","bad":"If you will be free, I will call you.","good":"If you <b>are</b> free, I will call you.","goodPlain":"If you are free, I will call you.","rule":"Після if, when, until, as soon as, unless майбутнє виражаємо Present Simple. Will лишається в головній частині."},{"title":"«Коли я виросту, стану детективом»","bad":"When I will grow up, I will become a detective.","good":"When I <b>grow</b> up, I will become a detective.","goodPlain":"When I grow up, I will become a detective.","rule":"Те саме після when: підрядна частина в Present Simple."},{"title":"«Я не піду, поки він не скаже»","bad":"I won't go until he will tell me.","good":"I won't go until he <b>tells</b> me.","goodPlain":"I won't go until he tells me.","rule":"Після until і till — теперішній час, а не will."},{"title":"«Якщо ти не поспішиш, запізнишся»","bad":"Unless you don't hurry, you will be late.","good":"Unless you <b>hurry</b>, you will be late.","goodPlain":"Unless you hurry, you will be late.","rule":"Unless уже містить заперечення (= if … not), тому not не додаємо."},{"title":"«Що ти робитимеш, якщо не отримаєш диплом?»","bad":"What will you do unless you get a diploma?","good":"What will you do <b>if</b> you <b>don't</b> get a diploma?","goodPlain":"What will you do if you don't get a diploma?","rule":"У питаннях unless не вживається: потрібне if … not."}]}$g29$::jsonb, null, 3, $g30$cond_first$g30$
from public.topics where slug = $g31$conditionals$g31$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$ct_5$g32$, $g33$Другий тип: нереальне зараз$g33$, $g34$elementary$g34$, $g35$formula$g35$, $g36${"step":"Другий тип","kicker":"Нереальна умова","lead":"Умовні речення другого типу (Second Conditional) говорять про <b>нереальну або малоймовірну</b> ситуацію в теперішньому чи майбутньому. Англійська «відсуває» час назад: після if стоїть Past Simple, хоча сенс теперішній.","tiles":[{"role":"умова","label":"If + Past Simple","tone":"colour"},{"role":"наслідок","label":"would / could / might + V","tone":"noun"}],"legend":[{"tone":"colour","label":"If he had free time = але вільного часу в нього немає"},{"tone":"noun","label":"Would + дієслово без to; could і might додають відтінок «міг би»"}],"examples":[{"text":"We <b>would go</b> to the skating rink <b>if</b> you <b>could</b> skate.","plain":"We would go to the skating rink if you could skate.","note":"але ти не вмієш кататися"},{"text":"<b>If</b> he <b>had</b> free time, he <b>would visit</b> us.","plain":"If he had free time, he would visit us.","note":"але вільного часу в нього немає"},{"text":"<b>If</b> the weather <b>were</b> fine, we <b>would play</b> tennis.","plain":"If the weather were fine, we would play tennis.","note":"але погода не гарна"}],"note":"Після if для to be вживаємо форму <b>were</b> для всіх осіб: <i>If I were you…</i>, <i>If she were here…</i>."}$g36$::jsonb, null, 4, $g37$cond_second$g37$
from public.topics where slug = $g38$conditionals$g38$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$ct_6$g39$, $g40$Порада: If I were you…$g40$, $g41$elementary$g41$, $g42$cases$g42$, $g43${"kicker":"Порада й «на вашому місці»","lead":"Другий тип умовних речень вживаємо й для порад. Це українське «на вашому місці я би…».","cards":[{"icon":"1","title":"If I were you + would + V","text":"Ми уявляємо себе на місці співрозмовника й кажемо, що зробили б.","example":"<b>If I were you</b>, I would eat more fruit.","examplePlain":"If I were you, I would eat more fruit."},{"icon":"2","title":"Were для всіх осіб","text":"У фразі If I were you форма were, а не was. Так само If he were older.","example":"If he <b>were</b> older, he could ride a motorbike.","examplePlain":"If he were older, he could ride a motorbike."},{"icon":"3","title":"Порада на проблему","text":"Називаємо проблему, а потім даємо пораду через would.","example":"I've got a terrible headache. — If I were you, I <b>would take</b> an aspirin.","examplePlain":"I've got a terrible headache. — If I were you, I would take an aspirin."},{"icon":"4","title":"Переклад: «на вашому місці»","text":"Українське «на вашому місці я би сказав правду» відповідає If I were you, I would tell the truth.","example":"<b>If I were you</b>, I wouldn't jump to conclusions.","examplePlain":"If I were you, I wouldn't jump to conclusions."}]}$g43$::jsonb, null, 5, $g44$cond_second$g44$
from public.topics where slug = $g45$conditionals$g45$
