insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$ct_7$g46$, $g47$Третій тип: нереальне минуле$g47$, $g48$intermediate$g48$, $g49$formula$g49$, $g50${"step":"Третій тип","kicker":"Те, що вже не змінити","lead":"Умовні речення третього типу (Third Conditional) говорять про ситуацію, яка була <b>нереальною в минулому</b>: щось не сталося, і це вже не змінити. Тому ними виражають жаль або критику.","tiles":[{"role":"умова","label":"If + Past Perfect","tone":"colour"},{"role":"наслідок","label":"would / could / might + have + V3","tone":"noun"}],"legend":[{"tone":"colour","label":"Past Perfect або Past Perfect Continuous: <i>If she had studied harder</i>"},{"tone":"noun","label":"Would have + третя форма: <i>she wouldn't have failed</i>"}],"examples":[{"text":"We <b>would have done</b> the work on time <b>if</b> he <b>had agreed</b> to help us.","plain":"We would have done the work on time if he had agreed to help us.","note":"але він не погодився"},{"text":"<b>If</b> she <b>had studied</b> harder, she <b>wouldn't have failed</b> her exam.","plain":"If she had studied harder, she wouldn't have failed her exam.","note":"але вона мало вчилась і не склала"},{"text":"<b>If</b> Greg <b>had been</b> more careful, he <b>wouldn't have broken</b> his arm.","plain":"If Greg had been more careful, he wouldn't have broken his arm.","note":"жаль про минуле"}],"note":"Будь-який минулий момент: <i>If you had called the doctor in time…</i> Українське «якби» без уточнення часу перекладаємо за змістом: було чи ні."}$g50$::jsonb, null, 6, $g51$cond_third$g51$
from public.topics where slug = $g52$conditionals$g52$
