insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$ct_8$g53$, $g54$Стоп-калька: would після if$g54$, $g55$intermediate$g55$, $g56$traps$g56$, $g57${"kicker":"Другий і третій типи","lead":"Українське «б» стоїть і в умові, і в наслідку: «якби я мав, я б купив». В англійській would живе лише в наслідку.","items":[{"title":"«Якби в мене були гроші, я б купив»","bad":"If I would have money, I would buy it.","good":"If I <b>had</b> money, I <b>would buy</b> it.","goodPlain":"If I had money, I would buy it.","rule":"Другий тип: після if — Past Simple, would лише в головній частині."},{"title":"«Якби я був на вашому місці»","bad":"If I am you, I would tell the truth.","good":"If I <b>were</b> you, I would tell the truth.","goodPlain":"If I were you, I would tell the truth.","rule":"Нереальна ситуація: if I were you (були, а не am)."},{"title":"«Якби ти попросив раніше, я б купив»","bad":"If you would have asked earlier, I would have bought it.","good":"If you <b>had asked</b> earlier, I <b>would have bought</b> it.","goodPlain":"If you had asked earlier, I would have bought it.","rule":"Третій тип: після if — Past Perfect, would have лише в наслідку."},{"title":"«Якби я знав, я б не прийшов»","bad":"If I knew, I wouldn't have come.","good":"If I <b>had known</b>, I wouldn't have come.","goodPlain":"If I had known, I wouldn't have come.","rule":"Про минуле після if потрібен Past Perfect: Past Simple дав би нереальне теперішнє."}]}$g57$::jsonb, null, 7, $g58$cond_third$g58$
