insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g60$th_1$g60$, $g61$Другий і третій тип: якби…$g61$, $g62$elementary$g62$, $g63$formula$g63$, $g64${"step":"Нереальні умови","kicker":"Базове розуміння","lead":"Коли умова нереальна, англійська «відсуває» час на крок назад. <b>Past Simple</b> говорить про нереальне теперішнє, <b>Past Perfect</b> — про нереальне минуле.","tiles":[{"role":"умова","label":"If + Past Simple","tone":"colour"},{"role":"наслідок","label":"would + bare infinitive","tone":"noun"}],"legend":[{"tone":"colour","label":"Тип 2: нереально зараз (If + Past Simple → would + V)"},{"tone":"noun","label":"Тип 3: нереально в минулому (If + Past Perfect → would have + V3)"}],"examples":[{"text":"If I <b>were</b> you, I <b>would leave</b> now.","plain":"If I were you, I would leave now.","note":"тип 2 · зараз"},{"text":"If I <b>had known</b> before, I <b>wouldn't have come</b>.","plain":"If I had known before, I wouldn't have come.","note":"тип 3 · минуле"},{"text":"If I <b>hadn't forgotten</b> my passport, I <b>could have travelled</b> abroad.","plain":"If I hadn't forgotten my passport, I could have travelled abroad.","note":"тип 3"},{"text":"If I <b>hadn't lost</b> my costume, I <b>could go</b> swimming now.","plain":"If I hadn't lost my costume, I could go swimming now.","note":"мішаний: минуле → зараз"}],"note":"Після <b>if</b> дієслово to be у Past Simple може мати форму <b>were</b> для всіх осіб: <i>If I were you</i> (так, а не <s>If I was you</s>, звучить правильніше й для іспитів)."}$g64$::jsonb, null, 8, $g65$cond_unreal$g65$
