insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g67$th_2$g67$, $g68$Замість if: unless, provided, only if та інверсія$g68$, $g69$intermediate$g69$, $g70$cases$g70$, $g71${"step":"Інші способи","kicker":"Конструкції на вибір","lead":"Умову можна передати не лише словом <b>if</b>. Дві конструкції змінюють порядок слів, їх треба впізнавати.","cards":[{"icon":"≠","title":"Unless = if … not","text":"Після <b>unless</b> дієслово стоїть у ствердній формі, <b>not</b> не додаємо.","example":"<b>Unless</b> you lend us money, we won't go.","examplePlain":"Unless you lend us money, we won't go."},{"icon":"✓","title":"Provided / as long as = if","text":"Умова, яка має виконатися: «за умови, що». Після них — теперішній час, а не will.","example":"You can borrow it <b>provided</b> you give it back.","examplePlain":"You can borrow it provided you give it back."},{"icon":"!","title":"Only if + інверсія","text":"Якщо <b>only if</b> стоїть на початку речення, у головній частині порядок слів як у питанні.","example":"<b>Only if</b> he changes it <b>will we sign</b> the contract.","examplePlain":"Only if he changes it will we sign the contract."},{"icon":"H","title":"Had + підмет + V3","text":"Інверсія без if для третього типу. Означає те саме, що <b>If … had</b>.","example":"<b>Had he not forgotten</b> the invitation, he would have gone.","examplePlain":"Had he not forgotten the invitation, he would have gone."},{"icon":"W","title":"Were + підмет","text":"Інверсія без if для другого типу, часто в порадах.","example":"<b>Were I</b> you, I would look for a better job.","examplePlain":"Were I you, I would look for a better job."},{"icon":"S","title":"Should + підмет + V","text":"Інверсія для реальної, але малоймовірної умови.","example":"We won't finish <b>should John not</b> turn up.","examplePlain":"We won't finish should John not turn up."}]}$g71$::jsonb, null, 9, $g72$cond_unreal$g72$
