insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g74$th_3$g74$, $g75$Wish: чотири ситуації$g75$, $g76$elementary$g76$, $g77$cases$g77$, $g78${"step":"Wish","kicker":"Що ми хочемо змінити","lead":"Після <b>I wish</b> (або <b>If only</b>) дієслово «відсувається» назад. Форма залежить від того, про що жаль.","cards":[{"icon":"1","title":"Жаль про теперішнє: Past Simple","text":"Ситуація зараз не така, як ми хочемо.","example":"I wish we <b>were</b> on holiday. (It's a pity we aren't.)","examplePlain":"I wish we were on holiday. It's a pity we aren't."},{"icon":"2","title":"Бракує вміння: could + V","text":"Жаль, що ми чогось не вміємо.","example":"I wish I <b>could speak</b> French. (BUT I can't.)","examplePlain":"I wish I could speak French. But I can't."},{"icon":"3","title":"Жаль про минуле: Past Perfect","text":"Щось сталося чи не сталося, і ми про це шкодуємо.","example":"I wish you <b>had listened</b> to me. (BUT you didn't.)","examplePlain":"I wish you had listened to me. But you didn't."},{"icon":"4","title":"Бажання змін: would + V","text":"Хочемо, щоб хтось змінив поведінку або щоб щось змінилось. Підмети різні, зміна малоймовірна.","example":"I wish he <b>would stop</b> lying. I wish it <b>would stop</b> snowing.","examplePlain":"I wish he would stop lying. I wish it would stop snowing."}],"axis":{"title":"Правило пальця","points":[{"label":"зараз","text":"<b>Past Simple</b>"},{"label":"уміння","text":"<b>could</b>"},{"label":"минуле","text":"<b>Past Perfect</b>"},{"label":"зміна","text":"<b>would</b>"}],"note":"Після I wish можна було б сказати <b>were</b> замість was для всіх осіб: <i>I wish he were / was more helpful.</i>"}}$g78$::jsonb, null, 10, $g79$cond_wish$g79$
from public.topics where slug = $g80$conditionals$g80$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g81$th_4$g81$, $g82$Стоп-калька: wish і would$g82$, $g83$intermediate$g83$, $g84$traps$g84$, $g85${"step":"Стоп-калька 1","kicker":"Захист від рідної мови","lead":"Українське «хотів би, щоб…» часто переносять на wish дослівно. Ось типові збої.","items":[{"title":"«Шкода, що я не вмію водити»","bad":"I wish I can drive.","good":"I wish I <b>could</b> drive.","goodPlain":"I wish I could drive.","rule":"Після <i>wish</i> дієслово «відсувається»: can → could."},{"title":"«Шкода, що ми не на канікулах»","bad":"I wish we are on holiday.","good":"I wish we <b>were</b> on holiday.","goodPlain":"I wish we were on holiday.","rule":"Теперішній жаль — Past Simple, для to be краще <i>were</i>."},{"title":"«Шкода, що я не пішов»","bad":"I wish I didn't go.","good":"I wish I <b>hadn't gone</b>.","goodPlain":"I wish I hadn't gone.","rule":"Жаль про минуле — Past Perfect."},{"title":"«Хотів би я бути багатшим» (про себе)","bad":"I wish I would be richer.","good":"I wish I <b>were</b> richer.","goodPlain":"I wish I were richer.","rule":"Wish і would мають різні підмети. Про себе <s>I wish I would</s> не кажемо."},{"title":"«Шкода, що він так багато скаржиться»","bad":"I wish he doesn't complain.","good":"I wish he <b>wouldn't</b> complain.","goodPlain":"I wish he wouldn't complain.","rule":"Роздратування чужою звичкою: <i>wish + would</i>."},{"title":"«Шкода, що йде сніг»","bad":"I wish it stops snowing.","good":"I wish it <b>would stop</b> snowing.","goodPlain":"I wish it would stop snowing.","rule":"Хочемо зміни в майбутньому (і сумніваємось у ній): wish + would + V."}]}$g85$::jsonb, null, 11, $g86$cond_wish$g86$
from public.topics where slug = $g87$conditionals$g87$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g88$th_5$g88$, $g89$Unreal Past: Past Simple і Past Perfect без минулого$g89$, $g90$intermediate$g90$, $g91$cases$g91$, $g92${"step":"Unreal Past","kicker":"Час «відсувається»","lead":"Past Simple може говорити про уявне теперішнє, а Past Perfect про уявне минуле. Це відбувається в шести конструкціях.","cards":[{"icon":"if","title":"Умовні речення","text":"Тип 2 — Past Simple, тип 3 — Past Perfect.","example":"If I <b>were</b> you, I'd leave. If I <b>had known</b>, I wouldn't have come.","examplePlain":"If I were you, I'd leave. If I had known, I wouldn't have come."},{"icon":"W","title":"Wish / if only","text":"Past Simple — теперішнє, Past Perfect — минуле.","example":"I wish she <b>worked</b> more efficiently. If only he <b>hadn't lied</b> to me.","examplePlain":"I wish she worked more efficiently. If only he hadn't lied to me."},{"icon":"R","title":"I'd rather / sooner + інший підмет","text":"Past Simple — про теперішнє й майбутнє, Past Perfect — про минуле.","example":"I'd rather you <b>left</b> the files here. I'd rather you <b>had not spoken</b> like that.","examplePlain":"I'd rather you left the files here. I'd rather you had not spoken like that."},{"icon":"S","title":"Suppose / supposing","text":"Уявна ситуація: Past Simple — про теперішнє, Past Perfect — про минуле.","example":"Suppose you <b>found</b> money, what would you do? Suppose she <b>hadn't reminded</b> you, would you have remembered?","examplePlain":"Suppose you found money, what would you do? Suppose she hadn't reminded you, would you have remembered?"},{"icon":"≈","title":"As if / as though","text":"Неправдиве порівняння: Past Simple — про теперішнє, Past Perfect — про минуле.","example":"He acts as if he <b>were</b> a genius. She looked at me as if she <b>had never seen</b> me before.","examplePlain":"He acts as if he were a genius. She looked at me as if she had never seen me before."},{"icon":"T","title":"It's (about / high) time","text":"«Давно пора». Дієслово у Past Simple, а сенс — теперішній.","example":"It's about time you <b>learnt</b> to drive.","examplePlain":"It's about time you learnt to drive."}]}$g92$::jsonb, null, 12, $g93$cond_unrealpast$g93$
from public.topics where slug = $g94$conditionals$g94$
