insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g95$th_6$g95$, $g96$Had better: «краще б…»$g96$, $g97$elementary$g97$, $g98$formula$g98$, $g99${"step":"Had better","kicker":"Порада з тиском","lead":"<b>Had better</b> звучить як порада, але майже з попередженням. Значення таке саме, як у <b>should</b>.","tiles":[{"role":"підмет","label":"I / you / he","tone":"noun"},{"role":"had better","label":"had better (not)","tone":"colour"},{"role":"bare infinitive","label":"+ V","tone":"age"}],"legend":[{"tone":"colour","label":"Про теперішнє й майбутнє: had better + V"},{"tone":"age","label":"Про минуле: It would have been better if + Past Perfect"}],"examples":[{"text":"He <b>had better not wait</b> any longer. (= He should not wait any longer.)","plain":"He had better not wait any longer.","note":"теперішнє / майбутнє"},{"text":"It <b>would have been better if</b> he <b>had phoned</b> us.","plain":"It would have been better if he had phoned us.","note":"минуле"},{"text":"You'<b>d better not wake</b> her up.","plain":"You'd better not wake her up.","note":"заперечення"}],"note":"Форма завжди <b>had</b>, але мова про теперішнє чи майбутнє. Після had better — інфінітив <b>без to</b>."}$g99$::jsonb, null, 13, $g100$cond_rather$g100$
