insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g102$th_7$g102$, $g103$Would rather і prefer: перевага$g103$, $g104$intermediate$g104$, $g105$cases$g105$, $g106${"step":"Would rather","kicker":"Що ми обираємо","lead":"Конструкції зі схожим значенням «віддаю перевагу» відрізняються формою дієслова після них.","cards":[{"icon":"1","title":"I'd rather + той самий підмет","text":"Після <b>I'd rather</b> — bare infinitive: про теперішнє й майбутнє — Present, про минуле — Perfect (have + V3).","example":"I'd rather <b>stay</b> in tonight. I'd rather <b>not have taken</b> the bus.","examplePlain":"I'd rather stay in tonight. I'd rather not have taken the bus."},{"icon":"2","title":"I'd rather + інший підмет","text":"Тут діє Unreal Past: Past Simple для теперішнього й майбутнього, Past Perfect для минулого.","example":"I'd rather you <b>didn't shout</b> so much. I'd rather you <b>had come</b> with me.","examplePlain":"I'd rather you didn't shout so much. I'd rather you had come with me."},{"icon":"3","title":"Prefer: загальна перевага","text":"<b>Prefer + gerund / noun + to + gerund / noun</b>.","example":"I prefer <b>watching</b> TV <b>to reading</b> books.","examplePlain":"I prefer watching TV to reading books."},{"icon":"4","title":"Prefer + to-інфінітив + rather than","text":"Загальна перевага: <b>prefer to V rather than V</b>. Після rather than — bare infinitive.","example":"I prefer <b>to eat</b> what I want <b>rather than count</b> calories.","examplePlain":"I prefer to eat what I want rather than count calories."},{"icon":"5","title":"Would prefer: конкретний вибір","text":"Одна конкретна ситуація: <b>would prefer to V rather than V</b>.","example":"I'd prefer <b>to play</b> football <b>rather than watch</b> it.","examplePlain":"I'd prefer to play football rather than watch it."},{"icon":"6","title":"Would rather + V + than + V","text":"Те саме, але без to в обох частинах.","example":"I'd rather <b>ski</b> than <b>skate</b>.","examplePlain":"I'd rather ski than skate."}]}$g106$::jsonb, null, 14, $g107$cond_rather$g107$
