  ($g131$cond_exT23_4$g131$, $g132$order$g132$, $g133$intermediate$g133$, $g134${"id":"cond_exT23_4","level":"intermediate","group":"T23","gord":23,"no":4,"groupTitle":"Exercise 23 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["keys","you","your","lose","will","What","do","you","if"],"answer":"What will you do if you lose your keys","hint":"Питання: What will you do + if + Present Simple"}$g134$, 3, $g135$cond_first$g135$),
  ($g136$cond_exT23_5$g136$, $g137$order$g137$, $g138$intermediate$g138$, $g139${"id":"cond_exT23_5","level":"intermediate","group":"T23","gord":23,"no":5,"groupTitle":"Exercise 23 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["will","arrive","when","I","you","I","phone"],"answer":"I will phone you when I arrive","hint":"Головна частина, потім when + Present Simple"}$g139$, 4, $g140$cond_first$g140$),
  ($g141$cond_exT26_1$g141$, $g142$order$g142$, $g143$intermediate$g143$, $g144${"id":"cond_exT26_1","level":"intermediate","group":"T26","gord":26,"no":1,"groupTitle":"Exercise 26 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["would","I","were","you","truth","If","tell","the","I"],"answer":"If I were you I would tell the truth","altAnswer":"I would tell the truth if I were you","hint":"If I were you + would + V"}$g144$, 5, $g145$cond_second$g145$),
  ($g146$cond_exT26_2$g146$, $g147$order$g147$, $g148$intermediate$g148$, $g149${"id":"cond_exT26_2","level":"intermediate","group":"T26","gord":26,"no":2,"groupTitle":"Exercise 26 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["a","lottery","won","bigger","house","if","buy","the","would","I","I"],"answer":"I would buy a bigger house if I won the lottery","hint":"Would + V, потім if + Past Simple"}$g149$, 6, $g150$cond_second$g150$),
  ($g151$cond_exT26_3$g151$, $g152$order$g152$, $g153$intermediate$g153$, $g154${"id":"cond_exT26_3","level":"intermediate","group":"T26","gord":26,"no":3,"groupTitle":"Exercise 26 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["French","If","he","more","would","he","had","time","learn"],"answer":"If he had more time he would learn French","hint":"If + Past Simple, would + V"}$g154$, 7, $g155$cond_second$g155$),
  ($g156$cond_exT26_4$g156$, $g157$order$g157$, $g158$intermediate$g158$, $g159${"id":"cond_exT26_4","level":"intermediate","group":"T26","gord":26,"no":4,"groupTitle":"Exercise 26 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["ghost","if","What","would","a","you","do","you","saw"],"answer":"What would you do if you saw a ghost","hint":"Питання: What would you do + if + Past Simple"}$g159$, 8, $g160$cond_second$g160$),
  ($g161$cond_exT26_5$g161$, $g162$order$g162$, $g163$intermediate$g163$, $g164${"id":"cond_exT26_5","level":"intermediate","group":"T26","gord":26,"no":5,"groupTitle":"Exercise 26 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["would","out","wasn't","go","it","raining","We","if"],"answer":"We would go out if it wasn't raining","hint":"Would + V, потім if + Past Simple"}$g164$, 9, $g165$cond_second$g165$),
  ($g166$cond_exT29_1$g166$, $g167$order$g167$, $g168$intermediate$g168$, $g169${"id":"cond_exT29_1","level":"intermediate","group":"T29","gord":29,"no":1,"groupTitle":"Exercise 29 · типи 1–3","instruction":"Put the words in the correct order.","prefix":"","scrambled":["If","I","I","come","known","would","have","had"],"answer":"If I had known I would have come","altAnswer":"I would have come if I had known","hint":"If + Past Perfect, would have + V3"}$g169$, 10, $g170$cond_third$g170$),
